const functionList=[['content.create','Create content','Write and edit drafts.','Content'],['content.approve','Approve content','Review content submitted by others.','Content'],['content.publish','Schedule & publish','Schedule or publish approved content.','Content'],['inbox.respond','Respond to residents','View conversations and prepare replies.','Engagement'],['reports.view','View reports','View analytics and export reports.','Reporting'],['ads.create','Create ads','Build advertising drafts.','Advertising'],['ads.manage','Manage ads','Edit and manage existing campaigns.','Advertising'],['ads.accounts.add','Add ad accounts','Register ad accounts for administrator review.','Advertising']];
const permissionKey='ngyn-user-access-v2';
let accessUsers;try{accessUsers=JSON.parse(localStorage.getItem(permissionKey))||groupData.users.map((u,i)=>({...u,id:'user-'+i,status:'Active',functions:i===0?functionList.map(f=>f[0]):['content.create'],channels:i===0?groupData.channels.slice(0,3).map((_,j)=>'social-'+j):[],adAccounts:[]}))}catch{accessUsers=[]}
const socialResources=groupData.channels.map((c,i)=>({id:'social-'+i,name:c.name,detail:c.network}));
const adResources=[{id:'ads-communications',name:'Harbourview Communications',detail:'Meta ad account · Fictional'},{id:'ads-recreation',name:'Harbourview Recreation',detail:'Meta ad account · Fictional'}];
let userFilter='';
function saveAccessUsers(){localStorage.setItem(permissionKey,JSON.stringify(accessUsers))}
function installUsers(){if(document.querySelector('#users-nav'))return;const b=document.createElement('button');b.id='users-nav';b.innerHTML='<span class="ico"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 22v-3a8 8 0 0 1 16 0v3"/></svg></span>Users';document.querySelector('.nav').insertBefore(b,document.querySelector('#groups-nav'));b.onclick=showUsers}
function showUsers(){installUsers();document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));document.querySelector('#users-nav').classList.add('active');document.querySelector('.crumb strong').textContent='User management';document.querySelector('#main').innerHTML=`<div class="page-head groups-heading"><div><div class="eyebrow">ADMINISTRATION / PEOPLE</div><h2>Users</h2><p>Add your team. Choose what they can do and where they can do it.</p></div><button class="btn primary" id="new-user">＋ Add user</button></div><div class="access-explainer"><div><strong>1. Add a person</strong><span>Name and login email</span></div><span class="flow-arrow">→</span><div><strong>2. Enable functions</strong><span>Choose what they can do</span></div><span class="flow-arrow">→</span><div><strong>3. Assign accounts</strong><span>Choose where permissions apply</span></div><div class="default-lock">No accounts assigned = no account access</div></div><section class="user-panel"><div class="user-list-header"><div><h3>Your team <span class="count-label">${accessUsers.length}</span></h3><p>New users start with no channel or ad-account access.</p></div><input id="user-search" aria-label="Search users" placeholder="Search name or login…" value="${safe(userFilter)}"></div><div id="user-list"></div></section>`;document.querySelector('#new-user').onclick=()=>editUser();document.querySelector('#user-search').oninput=e=>{userFilter=e.target.value;userRows()};userRows()}
function userRows(){const users=accessUsers.filter(u=>(u.name+' '+u.email).toLowerCase().includes(userFilter.toLowerCase()));document.querySelector('#user-list').innerHTML=`<div class="table-wrap"><table class="table user-table"><thead><tr><th>User / login</th><th>Invitation</th><th>Function access</th><th>Assigned accounts</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><div class="person"><div class="avatar">${safe(u.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><strong>${safe(u.name)}</strong><small>${safe(u.email)}</small></div></div></td><td><span class="badge ${u.status==='Active'?'ok':'warn'}">${safe(u.status)}</span></td><td><span>${u.functions.length} functions</span></td><td>${u.channels.length||u.adAccounts.length?`<span>${u.channels.length} channels · ${u.adAccounts.length} ad accounts</span>`:'<span class="no-access">No account access</span>'}</td><td><button class="btn" data-edit-user="${u.id}">Manage access</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No users found.</td></tr>'}</tbody></table></div>`;document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>editUser(b.dataset.editUser))}
function resourceList(resources,selected,type){return resources.map(r=>`<label class="resource-option"><input type="checkbox" name="${type}" value="${r.id}" ${selected.includes(r.id)?'checked':''}><span><strong>${safe(r.name)}</strong><small>${safe(r.detail)}</small></span></label>`).join('')}
function editUser(id){const existing=accessUsers.find(u=>u.id===id);const u=existing||{name:'',email:'',functions:[],channels:[],adAccounts:[],status:'Not invited'};modal(`<form id="user-access-form"><div class="modal-head"><div><div class="eyebrow">USER MANAGEMENT</div><h2>${existing?'Manage user':'Add user'}</h2></div><button type="button" data-close aria-label="Close user form">×</button></div><section class="access-section"><div class="section-heading"><span class="step-number">1</span><div><h3>Basic details</h3><p>The email address is their login.</p></div></div><div class="basic-fields"><div class="field"><label for="access-name">Full name</label><input id="access-name" required maxlength="100" value="${safe(u.name)}" placeholder="Alex Taylor" autocomplete="off"></div><div class="field"><label for="access-email">Login email</label><input id="access-email" type="email" required value="${safe(u.email)}" placeholder="alex@harbourview.example" autocomplete="off"></div></div><div class="invite-status"><span>Invitation: <strong>${safe(u.status)}</strong></span><small>Demo only · no email will be sent</small></div></section><section class="access-section"><div class="section-heading"><span class="step-number">2</span><div><h3>Function access</h3><p>Choose the actions this person can perform.</p></div></div><div class="function-options">${functionList.map(f=>`<label class="function-option"><input type="checkbox" name="functions" value="${f[0]}" ${u.functions.includes(f[0])?'checked':''}><span><strong>${f[1]}</strong><small>${f[2]}</small></span></label>`).join('')}</div><div class="permission-hint">Enabling a function does not give access to any account. Adding an ad account never grants access to it automatically.</div></section><section class="access-section"><div class="section-heading"><span class="step-number">3</span><div><h3>Account assignments</h3><p>Function permissions apply only to the accounts selected below.</p></div></div><div class="assignment-summary" id="assignment-summary"></div><details ${u.channels.length?'open':''}><summary>Social channels <span>${socialResources.length} available</span></summary><div class="resource-list">${resourceList(socialResources,u.channels,'channels')}</div></details><details ${u.adAccounts.length?'open':''}><summary>Ad accounts <span>${adResources.length} available</span></summary><div class="resource-list">${resourceList(adResources,u.adAccounts,'adAccounts')}</div></details><div class="permission-hint">No access to unassigned channels or ad accounts. Advertising spend always needs separate authorization.</div></section><p id="user-form-error" role="alert"></p><div class="user-form-footer"><button type="button" class="btn" data-close>Cancel</button><div class="actions"><button class="btn" type="submit" name="intent" value="save">Save user</button><button class="btn primary" type="submit" name="intent" value="invite">${existing&&u.status==='Invited (demo)'?'Resend demo invitation':'Save & invite (demo)'}</button></div></div></form>`);const box=document.querySelector('.modal-box');box.classList.add('user-access-dialog');box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label',existing?'Manage user':'Add user');document.querySelector('#access-name').focus();const summary=()=>{const channelCount=document.querySelectorAll('[name="channels"]:checked').length,adCount=document.querySelectorAll('[name="adAccounts"]:checked').length;document.querySelector('#assignment-summary').textContent=channelCount||adCount?`${channelCount} channels and ${adCount} ad accounts selected. All other accounts remain inaccessible.`:'No accounts assigned. This user cannot access any channel or ad account.'};summary();document.querySelectorAll('[name="channels"],[name="adAccounts"]').forEach(c=>c.onchange=summary);document.querySelector('#user-access-form').onsubmit=e=>{e.preventDefault();const name=document.querySelector('#access-name').value.trim(),email=document.querySelector('#access-email').value.trim().toLowerCase();if(!name){document.querySelector('#user-form-error').textContent='Enter a full name.';return}if(accessUsers.some(x=>x.id!==id&&x.email.toLowerCase()===email)){document.querySelector('#user-form-error').textContent='This login email already belongs to a user.';return}const get=n=>[...document.querySelectorAll(`[name="${n}"]:checked`)].map(c=>c.value);const invite=e.submitter?.value==='invite';const saved={...u,id:id||crypto.randomUUID(),name,email,functions:get('functions'),channels:get('channels'),adAccounts:get('adAccounts'),status:invite?'Invited (demo)':u.status};if(existing)accessUsers[accessUsers.indexOf(existing)]=saved;else accessUsers.push(saved);saveAccessUsers();close();showUsers();toast(invite?'Demo invitation recorded. No email sent.':'User and account permissions saved.')}}
// A function grant and a matching explicit account assignment are both required.
function hasAccountFunction(user,functionId,resourceType,resourceId){return Boolean(user&&user.functions.includes(functionId)&&['channels','adAccounts'].includes(resourceType)&&user[resourceType].includes(resourceId))}
const accessExample={functions:['content.create','ads.create'],channels:['assigned-channel'],adAccounts:[]};
console.assert(hasAccountFunction(accessExample,'content.create','channels','assigned-channel')===true,'Assigned channel permits enabled function');
console.assert(hasAccountFunction(accessExample,'content.publish','channels','assigned-channel')===false,'Disabled function denied');
console.assert(hasAccountFunction(accessExample,'content.create','channels','other-channel')===false,'Unassigned channel denied');
console.assert(hasAccountFunction(accessExample,'ads.create','adAccounts','any-ad-account')===false,'Ad accounts denied by default');
document.addEventListener('click',e=>{const groupAdd=e.target.closest('#add-record');if(groupAdd&&activeTab==='users'){e.preventDefault();e.stopImmediatePropagation();editUser()}const group=e.target.closest('#groups-nav');if(group)setTimeout(installUsers,0)},true);
const renderBeforeUsers=render;render=function(){renderBeforeUsers();refine();installGroups();installUsers()};
installUsers();showUsers();
